/**
 * Golf AI provider client and bounded tool-calling loop.
 *
 * The LLM is responsible for selecting appropriate analytics tools and
 * explaining their results; it is not authoritative for metric calculation.
 * Tool execution remains inside the application and visual payloads are built
 * deterministically from tool history rather than generated by the model.
 */
const OpenAI = require("openai");
const Anthropic = require("@anthropic-ai/sdk");

const { GOLF_AI_TOOLS, executeGolfAITool } = require("./golfAIOpenAITools");
const { buildGolfAIVisuals } = require("./golfAIVisuals");

/*
 * OpenRouter exposes an OpenAI-compatible API, allowing the existing OpenAI
 * SDK to be used with a different base URL. Provider-specific configuration is
 * intentionally concentrated in this module so it can be replaced later.
 */
const openrouter = new OpenAI({
    apiKey: process.env.OPENROUTER_API_KEY,
    baseURL: "https://openrouter.ai/api/v1"
});

/*
 * Native Anthropic client. The API key may be absent while OpenRouter is the
 * active provider; provider-specific validation happens when a request runs.
 */
const anthropic = new Anthropic({
    apiKey: process.env.ANTHROPIC_API_KEY
});

/* Convert the application's provider-neutral tool definitions to chat tools. */
const OPENROUTER_TOOLS = GOLF_AI_TOOLS.map(function (tool) {
    return {
        type: "function",
        function: {
            name: tool.name,
            description: tool.description,
            parameters: tool.parameters,
            strict: tool.strict
        }
    };
});

/*
 * Anthropic uses the same application-owned tool definitions but expects the
 * JSON schema under input_schema rather than OpenAI's function.parameters.
 */
const ANTHROPIC_TOOLS = GOLF_AI_TOOLS.map(function (tool) {
    return {
        name: tool.name,
        description: tool.description,
        input_schema: tool.parameters
    };
});

/*
 * Hard limits prevent unexpectedly large prompts or runaway tool loops from
 * consuming unbounded provider/database work. The HTTP route also validates
 * question length; retaining the check here protects direct future callers.
 */
const MAX_QUESTION_LENGTH = 1000;
const MAX_TOOL_ROUNDS = 5;
const MAX_TOOL_CALLS = 8;

/*
 * Provider configuration is environment-driven so production models can be
 * changed without modifying application code. OpenRouter remains the active
 * provider while native Anthropic support is introduced separately.
 */
const GOLF_AI_PROVIDER = process.env.GOLF_AI_PROVIDER || "openrouter";

const OPENROUTER_MODEL =
    process.env.GOLF_AI_OPENROUTER_MODEL || "openrouter/free";

const ANTHROPIC_MODEL =
    process.env.GOLF_AI_ANTHROPIC_MODEL || "claude-sonnet-4-6";

/**
 * Sends a golfer question to the configured model and services any requested
 * analytics tools until the model returns a final textual answer. Failed tool
 * calls are returned to the model in a sanitised form so it can recover from
 * bad arguments without exposing internal implementation details.
 *
 * @returns {Object} Provider/model metadata for debugging, final content,
 * deterministic visuals and the internal tool history. The production route
 * intentionally strips debug fields before returning data to the frontend.
 */
function buildSystemPrompt() {
    return (
        "You are a golf performance analyst. " +
        "Use the supplied tools when golf performance data is needed. " +
        "The application's calculated statistics are authoritative. " +
        "Do not invent statistics or recalculate them from assumptions. " +
        "Only state facts that are directly supported by the tool results. " +
        "Do not infer the player's intention, strategy, reason for a club choice, " +
        "type of shot, recovery action, or cause of an outcome unless the tool " +
        "result explicitly establishes it. " +
        "For example, do not label a shot as a re-shot, relief shot, approach, " +
        "chip, pitch, lay-up, or unusual club choice merely from the shot sequence. " +
        "Shot outcome data is authoritative when interpreting where a shot ended. " +
        "Player-rated shot quality is subjective user input from 1 to 5 and must " +
        "not be presented as an objective measurement. " +
        "Recorded club distance is ball travel distance and is not necessarily " +
        "carry distance or an indication that longer is better. " +
        "Respect the metric direction metadata when deciding whether a change " +
        "is better or worse. " +
        "Consider sample size, telemetry coverage and data-quality limitations. " +
        "Do not claim strokes-gained analysis because benchmark data is not " +
        "currently available. " +
        "Use the most specific tool that can answer the question. " +
        "If the user asks about a specific hole, use get_hole directly rather " +
        "than retrieving the entire round first unless round-level context is " +
        "actually required. " +
        "Keep answers concise and useful to the golfer. " +
        "Shot-sequence interpretation rules: " +
        "- 'position' is where the recorded stroke starts. " +
        "- 'outcome' is the authoritative recorded result/end state of that stroke. " +
        "- Never describe 'position' as the result of that same stroke. " +
        "- A later stroke's position may differ from the previous stroke's outcome. " +
        "The data does not explain how the player moved between those states. " +
        "State the new recorded starting position literally and do not infer a drop, " +
        "re-tee, lost ball, relief, penalty procedure, or other intervening event. " +
        "- An outcome marked penalty=true represents a recorded penalty stroke. " +
        "Do not invent the cause of the penalty. " +
        "- Do not infer drops, re-shots, relief, replayed shots, shot intent, or " +
        "golf-rule procedures from the sequence unless explicitly provided by a tool. " +
        "- 'travelDistance' with type='recorded_travel' means recorded ball travel only. " +
        "It is not the starting distance to the hole and must not be described as a " +
        "'30-foot putt', 'putt from 30 feet', carry distance, or distance remaining. " +
        "- Player shot-quality ratings are subjective player-entered ratings. " +
        "Describe them as player-rated, not as objective assessments. " +
        "When describing a shot sequence, prefer literal statements such as " +
        "'started from X and the recorded outcome was Y' when a more natural " +
        "description would require an unsupported inference. " +
        "- 'scoringCategory' values such as 'doubleOrWorse' are analytical buckets, " +
        "not exact golf score labels. Never translate 'doubleOrWorse' into 'double bogey'. " +
        "When describing an individual hole, use the supplied scoreToPar value directly " +
        "(for example '+4') unless an exact score label is explicitly supplied by the tool. " +
        "Analytical reasoning rules: " +
        "- Separate observed data from interpretation. " +
        "- A change in one metric does not prove that it caused a change in another metric. " +
        "- Do not claim causal relationships unless a tool explicitly provides evidence for them. " +
        "- When recommending what to work on, describe areas as priorities to investigate " +
        "or practise based on the observed metrics, not as proven causes of scoring changes. " +
        "- Do not diagnose swing, technique, strategy, approach proximity, putting stroke, " +
        "or course-management problems unless the available tool data directly supports that conclusion. " +
        "- More greens in regulation does not inherently imply fewer putts per hole. " +
        "- Putts per hole alone cannot distinguish putting skill from starting putt distance " +
        "or approach proximity. " +
        "- Starting distance to the hole is not currently available. Do not infer it. " +
        "- Treat comparisons across a small number of rounds as recent patterns or signals, " +
        "not established long-term trends. " +
        "- State important sample-size or data-coverage limitations when they materially " +
        "affect a conclusion."
    );
}

/*
 * Executes one provider-neutral tool request and records the deterministic
 * history used to build frontend visuals.
 */
async function runToolCall(internalToolCall, serverContext, toolHistory) {
    let toolResult;
    let parsedArguments;

    try {
        parsedArguments = JSON.parse(internalToolCall.arguments);

        toolResult = await executeGolfAITool(internalToolCall, serverContext);
    } catch (error) {
        toolResult = {
            available: false,
            error: "TOOL_CALL_FAILED",
            message:
                "The requested golf analytics tool call could not be completed. " +
                "Check the tool name and arguments and try again if appropriate."
        };

        parsedArguments = parsedArguments || internalToolCall.arguments;
    }

    toolHistory.push({
        name: internalToolCall.name,
        arguments: parsedArguments,
        result: toolResult
    });

    return toolResult;
}

/*
 * OpenRouter/OpenAI-compatible execution loop. Existing production behaviour
 * is preserved while tool execution is shared with the Anthropic path.
 */
async function askOpenRouter(systemPrompt, userMessages, serverContext) {
    const messages = [
        {
            role: "system",
            content: systemPrompt
        },
        ...userMessages
    ];

    const toolHistory = [];
    let toolCallCount = 0;

    for (let toolRound = 0; toolRound < MAX_TOOL_ROUNDS; toolRound++) {
        const response = await openrouter.chat.completions.create({
            model: OPENROUTER_MODEL,
            messages: messages,
            tools: OPENROUTER_TOOLS,
            tool_choice: "auto"
        });

        if (!response.choices || response.choices.length === 0) {
            throw new Error("OpenRouter returned no response choices.");
        }

        const message = response.choices[0].message;

        const toolCalls = Array.isArray(message.tool_calls)
            ? message.tool_calls
            : [];

        if (toolCallCount + toolCalls.length > MAX_TOOL_CALLS) {
            const error = new Error(
                "Golf AI exceeded the maximum number of tool calls."
            );

            error.code = "GOLF_AI_TOOL_LIMIT";
            throw error;
        }

        toolCallCount += toolCalls.length;

        if (toolCalls.length === 0) {
            const content =
                typeof message.content === "string"
                    ? message.content.trim()
                    : "";

            if (!content) {
                const error = new Error("Golf AI returned an empty response.");
                error.code = "GOLF_AI_EMPTY_RESPONSE";
                throw error;
            }

            return {
                provider: "openrouter",
                model: response.model || OPENROUTER_MODEL,
                content,
                visuals: buildGolfAIVisuals(toolHistory),
                toolHistory
            };
        }

        messages.push({
            role: "assistant",
            content: message.content || null,
            tool_calls: toolCalls
        });

        for (const toolCall of toolCalls) {
            if (!toolCall.function || !toolCall.function.name) {
                throw new Error("OpenRouter returned an invalid tool call.");
            }

            const internalToolCall = {
                name: toolCall.function.name,
                arguments: toolCall.function.arguments || "{}"
            };

            const toolResult = await runToolCall(
                internalToolCall,
                serverContext,
                toolHistory
            );

            messages.push({
                role: "tool",
                tool_call_id: toolCall.id,
                content: JSON.stringify(toolResult)
            });
        }
    }

    const error = new Error(
        "Golf AI exceeded the maximum number of tool rounds."
    );
    error.code = "GOLF_AI_TOOL_LIMIT";
    throw error;
}

/*
 * Native Anthropic execution loop. Complete assistant content blocks are
 * retained before tool_result blocks are appended, preserving provider context
 * across tool rounds.
 */
async function askAnthropic(systemPrompt, userMessages, serverContext) {
    const messages = userMessages.map(function (message) {
        return {
            role: message.role,
            content: message.content
        };
    });

    const toolHistory = [];
    let toolCallCount = 0;

    for (let toolRound = 0; toolRound < MAX_TOOL_ROUNDS; toolRound++) {
        const response = await anthropic.messages.create({
            model: ANTHROPIC_MODEL,
            max_tokens: 1200,
            system: systemPrompt,
            messages: messages,
            tools: ANTHROPIC_TOOLS,
            tool_choice: {
                type: "auto"
            }
        });

        const contentBlocks = Array.isArray(response.content)
            ? response.content
            : [];

        const toolCalls = contentBlocks.filter(function (block) {
            return block && block.type === "tool_use";
        });

        if (toolCallCount + toolCalls.length > MAX_TOOL_CALLS) {
            const error = new Error(
                "Golf AI exceeded the maximum number of tool calls."
            );

            error.code = "GOLF_AI_TOOL_LIMIT";
            throw error;
        }

        toolCallCount += toolCalls.length;

        if (toolCalls.length === 0) {
            const content = contentBlocks
                .filter(function (block) {
                    return block && block.type === "text";
                })
                .map(function (block) {
                    return block.text;
                })
                .join("\n")
                .trim();

            if (!content) {
                const error = new Error("Golf AI returned an empty response.");
                error.code = "GOLF_AI_EMPTY_RESPONSE";
                throw error;
            }

            return {
                provider: "anthropic",
                model: response.model || ANTHROPIC_MODEL,
                content,
                visuals: buildGolfAIVisuals(toolHistory),
                toolHistory
            };
        }

        messages.push({
            role: "assistant",
            content: contentBlocks
        });

        const toolResults = [];

        for (const toolCall of toolCalls) {
            if (!toolCall.name || !toolCall.id) {
                throw new Error("Anthropic returned an invalid tool call.");
            }

            const toolInput =
                toolCall.input &&
                typeof toolCall.input === "object" &&
                !Array.isArray(toolCall.input)
                    ? toolCall.input
                    : {};

            const internalToolCall = {
                name: toolCall.name,
                arguments: JSON.stringify(toolInput)
            };

            const toolResult = await runToolCall(
                internalToolCall,
                serverContext,
                toolHistory
            );

            toolResults.push({
                type: "tool_result",
                tool_use_id: toolCall.id,
                content: JSON.stringify(toolResult)
            });
        }

        messages.push({
            role: "user",
            content: toolResults
        });
    }

    const error = new Error(
        "Golf AI exceeded the maximum number of tool rounds."
    );
    error.code = "GOLF_AI_TOOL_LIMIT";
    throw error;
}

/**
 * Sends a golfer question to the selected provider. The provider boundary uses
 * a messages array internally so persistent conversation history can be added
 * later without redesigning the provider-specific tool loops.
 */
async function askGolfAI(question, serverContext) {
    if (GOLF_AI_PROVIDER !== "openrouter" && GOLF_AI_PROVIDER !== "anthropic") {
        const error = new Error(
            "Unsupported golf AI provider: " + GOLF_AI_PROVIDER
        );

        error.code = "GOLF_AI_PROVIDER";
        throw error;
    }

    if (GOLF_AI_PROVIDER === "openrouter" && !process.env.OPENROUTER_API_KEY) {
        throw new Error("OPENROUTER_API_KEY is not configured.");
    }

    if (GOLF_AI_PROVIDER === "anthropic" && !process.env.ANTHROPIC_API_KEY) {
        throw new Error("ANTHROPIC_API_KEY is not configured.");
    }

    if (typeof question !== "string" || question.trim().length === 0) {
        const error = new Error("Golf AI question is required.");
        error.code = "GOLF_AI_VALIDATION";
        throw error;
    }

    const normalizedQuestion = question.trim();

    if (normalizedQuestion.length > MAX_QUESTION_LENGTH) {
        const error = new Error("Golf AI question is too long.");
        error.code = "GOLF_AI_VALIDATION";
        throw error;
    }

    const systemPrompt = buildSystemPrompt();
    /*
     * Conversation history is loaded and ownership-checked by the route.
     * Keep the provider-facing representation deliberately simple so the same
     * history can be consumed by OpenRouter and native Anthropic.
     */
    const conversationMessages =
        serverContext && Array.isArray(serverContext.conversationMessages)
            ? serverContext.conversationMessages
            : [];

    const userMessages = conversationMessages
        .filter(function (message) {
            return (
                message &&
                (message.role === "user" || message.role === "assistant") &&
                typeof message.content === "string" &&
                message.content.trim()
            );
        })
        .map(function (message) {
            return {
                role: message.role,
                content: message.content
            };
        });

    /*
     * The current question has not been persisted yet, so append it after the
     * stored history. It will only be written to MongoDB together with the
     * assistant response after the AI request succeeds.
     */
    userMessages.push({
        role: "user",
        content: normalizedQuestion
    });

    if (GOLF_AI_PROVIDER === "anthropic") {
        return askAnthropic(systemPrompt, userMessages, serverContext);
    }

    return askOpenRouter(systemPrompt, userMessages, serverContext);
}

module.exports = {
    askGolfAI
};
